      return i === 0 ? lower : lower[1].toUpperCase() + lower.slice(1);
    })
    .join('');
}
```

For "hello big world":
- i=0: "hello" → "hello" (correct)
- i=1: "big" → lower = "big", lower[1].toUpperCase() = "I", + lower.slice(1) = "ig" → "Iig" (wrong; should capitalize first char: "Big")
- i=2: "world" → lower[1].toUpperCase() = "O", + lower.slice(1) = "orld" → "Oorld" (should be "World")

